import { computed, ref } from 'vue';

type ChildNode = {
  id: string;
  label: string;
  checked: boolean;
};

const children = ref<ChildNode[]>([
  { id: 'c1', label: 'Child 1', checked: false },
  { id: 'c2', label: 'Child 2', checked: false },
  { id: 'c3', label: 'Child 3', checked: false }
]);

const checkedCount = computed(() => children.value.filter((child) => child.checked).length);

// The parent keeps no state: reading it derives from the children, and setting it (a click) writes every child.
const allChecked = computed({
  get: () => checkedCount.value === children.value.length,
  set: (checked: boolean) => {
    // Vue tracks changes made in place on reactive objects, so each child is updated directly.
    for (const child of children.value) {
      child.checked = checked;
    }
  }
});

// Some but not all: bound to the parent's indeterminate, which Vue sets as a DOM property.
const someChecked = computed(() => checkedCount.value > 0 && !allChecked.value);
